// Copies the ABIs that `forge build` leaves in out/ into src/abi/ as typed constants.
// Run `forge build` first, then `npm run sync-abis`. The generated files are committed so the
// frontend builds without Foundry installed.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const outDir = resolve(repoRoot, "frontend", "src", "abi");
const contracts = ["StakingApp", "StakingNFT", "StakingToken"];

mkdirSync(outDir, { recursive: true });

for (const name of contracts) {
  const artifact = JSON.parse(readFileSync(resolve(repoRoot, "out", `${name}.sol`, `${name}.json`), "utf8"));
  const camelName = name[0].toLowerCase() + name.slice(1);

  // `as const` keeps the literal types, which is what lets viem infer argument and return types.
  const source =
    `// Generated by scripts/sync-abis.mjs from out/${name}.sol/${name}.json. Do not edit.\n` +
    `export const ${camelName}Abi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;

  writeFileSync(resolve(outDir, `${camelName}.ts`), source);
  console.log(`${name}: ${artifact.abi.length} ABI entries -> src/abi/${camelName}.ts`);
}
